import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.X4qO_DBC.js";const u=JSON.parse('{"title":"曹俊","description":"","frontmatter":{},"headers":[],"relativePath":"曹俊-前端开发工程师-优化版.md","filePath":"曹俊-前端开发工程师-优化版.md","lastUpdated":1794251976000}'),n={name:"曹俊-前端开发工程师-优化版.md"};function i(l,e,s,g,d,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="曹俊" tabindex="-1">曹俊 <a class="header-anchor" href="#曹俊" aria-label="Permalink to &quot;曹俊&quot;">​</a></h1><p><strong>前端开发工程师</strong></p><p>3 年以上前端开发经验｜广州，可赴上海等城市工作<br> 电话：18773507481｜邮箱：caojun010214@gmail.com<br> GitHub：<a href="https://github.com/thosewhoyoulove" target="_blank" rel="noreferrer">https://github.com/thosewhoyoulove</a></p><h2 id="专业技能" tabindex="-1">专业技能 <a class="header-anchor" href="#专业技能" aria-label="Permalink to &quot;专业技能&quot;">​</a></h2><ul><li><strong>前端基础：</strong> 熟悉 JavaScript（ES6+）、TypeScript、HTML5、CSS3，理解异步编程、事件循环、浏览器渲染和 HTTP 通信，能够从状态、请求和浏览器执行过程定位复杂业务问题。</li><li><strong>React / Vue：</strong> 熟悉 React Hooks、Redux、Vue 2 / Vue 3，具备复杂状态建模、组件抽象、异步请求管理和高交互业务开发经验。</li><li><strong>工程化与架构：</strong> 熟悉 Webpack、Vite、npm Workspaces / Monorepo，参与 TypeScript SDK 分层、公共模块抽象、多产品复用和技术栈迁移。</li><li><strong>AI Agent 交互：</strong> 具备 AI Agent 前端开发经验，熟悉 SSE 流式解析、增量事件归并、会话生命周期、工具调用展示、人工确认和异步竞态处理。</li><li><strong>AI 辅助研发：</strong> 使用 Cursor、Codex 等工具辅助需求拆解、代码实现、重构和问题排查，重视代码审查、类型约束、测试与构建验证。</li></ul><h2 id="工作经历" tabindex="-1">工作经历 <a class="header-anchor" href="#工作经历" aria-label="Permalink to &quot;工作经历&quot;">​</a></h2><h3 id="广州探迹科技有限公司-前端开发工程师" tabindex="-1">广州探迹科技有限公司｜前端开发工程师 <a class="header-anchor" href="#广州探迹科技有限公司-前端开发工程师" aria-label="Permalink to &quot;广州探迹科技有限公司｜前端开发工程师&quot;">​</a></h3><p><strong>2025.05—至今</strong></p><ul><li>参与企业级 SaaS 搜索筛选、营销触达和 AI Agent 等业务模块，负责复杂交互、状态管理、技术方案落地和跨团队联调。</li><li>参与公共组件、TypeScript SDK 及 Agent 共享模块建设，围绕多产品复用、跨应用通信、流式状态管理和异步一致性进行开发与重构。</li></ul><h3 id="千瓦科技-上海-有限公司-web-前端开发工程师" tabindex="-1">千瓦科技（上海）有限公司｜Web 前端开发工程师 <a class="header-anchor" href="#千瓦科技-上海-有限公司-web-前端开发工程师" aria-label="Permalink to &quot;千瓦科技（上海）有限公司｜Web 前端开发工程师&quot;">​</a></h3><p><strong>2023.05—2025.05</strong></p><ul><li>参与物联网能源管理平台从 0 到 1 建设，负责业务页面、ECharts 数据可视化和公共组件开发。</li><li>主导 Vue 2 → Vue 3、Vuex → Pinia、vue-cli → Vite 的技术栈迁移，处理依赖兼容和构建配置问题；结合模块拆分与按需引入，将构建耗时由约 60 秒降至 15 秒，缩短约 75%。</li></ul><h2 id="项目经历" tabindex="-1">项目经历 <a class="header-anchor" href="#项目经历" aria-label="Permalink to &quot;项目经历&quot;">​</a></h2><h3 id="一、探迹销售-ai-agent-多产品流式交互平台" tabindex="-1">一、探迹销售 AI Agent｜多产品流式交互平台 <a class="header-anchor" href="#一、探迹销售-ai-agent-多产品流式交互平台" aria-label="Permalink to &quot;一、探迹销售 AI Agent｜多产品流式交互平台&quot;">​</a></h3><p><strong>前端开发｜React 19、Ant Design、Vite、SSE、npm Workspaces</strong></p><p><strong>项目背景：</strong> 面向企业销售场景构建 AI Agent 交互平台，支持流式会话、工具调用、文件展示和人工确认，并向 Sales、Tuoke 等业务产品复用通用会话能力。</p><p><strong>核心问题：</strong> Agent 一次执行会持续产生阶段、文本、工具和确认事件，前端需要把不稳定的网络数据转换成可追踪的会话状态；多个产品又需要共享这套能力，同时保留各自的接口和业务规则。</p><ul><li><strong>流式协议与事件归并：</strong> 基于 Fetch <code>ReadableStream</code> 实现 SSE 增量解析，处理网络分块、UTF-8 跨块字符和事件分帧；按 <code>event_id</code> 归并持续更新的业务事件，将流式数据转换为可展示的会话状态。</li><li><strong>异步竞态与会话隔离：</strong> 结合 <code>AbortController</code> 和执行序号管理流连接生命周期，在连续发送、切换会话和组件卸载时取消旧连接，并在回调提交前校验执行身份，避免过期结果污染当前会话。</li><li><strong>公共能力与业务扩展分层：</strong> 参与抽取 <code>@tungee/agent-core</code>，统一承载流式处理、会话状态和通用消息 UI；产品侧负责接口适配、鉴权、CRM 写入确认及其他业务扩展，降低多产品重复维护成本。</li><li><strong>结构化工具交互：</strong> 将工具调用、文件预览和人工确认等事件映射为对应 UI，区分执行中、等待确认、完成和错误等用户可见状态。</li></ul><h3 id="二、企业级高级筛选与-ai-智能搭建系统" tabindex="-1">二、企业级高级筛选与 AI 智能搭建系统 <a class="header-anchor" href="#二、企业级高级筛选与-ai-智能搭建系统" aria-label="Permalink to &quot;二、企业级高级筛选与 AI 智能搭建系统&quot;">​</a></h3><p><strong>前端开发｜2025.05—至今｜React、Redux、Ant Design、Webpack、SSE</strong></p><p><strong>项目背景：</strong> 面向企业客户检索场景，提供复杂条件组合、卡片 / 表格双视图和自然语言生成筛选条件能力。系统需要同时处理手动筛选、AI 任务、异步维度配置和页面返回后的任务恢复。</p><p><strong>核心问题：</strong> AI 生成条件必须进入已有的筛选、查询、保存和分享链路；如果条件归属、配置时序或请求生命周期没有明确边界，界面展示的条件可能与实际查询不一致。</p><ul><li><strong>工作区与结果状态隔离：</strong> 分离手动筛选和 AI 智能搭建的条件；分别维护卡片 / 表格视图的数据、分页和加载状态，并通过查询条件快照明确本次查询的输入，降低模式切换和视图切换时的状态串扰。</li><li><strong>AI 条件进入业务闭环：</strong> 基于 POST SSE 接收自然语言筛选任务，按阶段事件展示进度；任务就绪且条件对象可用后，统一回填既有筛选体系，继续支持人工调整、条件组保存和口令分享。</li><li><strong>异步回填一致性：</strong> 针对筛选维度配置与 AI 条件到达顺序不一致的问题，使用 <code>pendingValue</code> 暂存待回填条件，待配置就绪后再完成转换；将同一份条件快照传给回填和查询入口，减少旧状态被读取的风险。</li><li><strong>任务恢复与连接隔离：</strong> 结合 <code>taskId</code>、<code>requestId</code> 和 <code>AbortController</code> 管理服务端任务与前端连接；按用户和业务主体保存限时任务快照，支持页面返回后续接，嵌入场景关闭页面级缓存恢复以隔离不同宿主的生命周期。</li></ul><h3 id="三、营销触达核心-sdk-跨应用通信与呼叫能力复用" tabindex="-1">三、营销触达核心 SDK｜跨应用通信与呼叫能力复用 <a class="header-anchor" href="#三、营销触达核心-sdk-跨应用通信与呼叫能力复用" aria-label="Permalink to &quot;三、营销触达核心 SDK｜跨应用通信与呼叫能力复用&quot;">​</a></h3><p><strong>前端开发｜2025.10—2025.12｜TypeScript、React、SharedWorker、sip.js</strong></p><p><strong>项目背景：</strong> 面向多个业务系统提供统一呼叫能力。SDK 需要把业务页面、呼叫逻辑、状态模型和跨宿主通信连接起来，并在不同浏览器或宿主条件下保留可用的单页能力。</p><ul><li><strong>分层与统一入口：</strong> 基于既有 BLL / Model / Bridge 分层参与开发和维护，将呼叫业务操作、状态模型和宿主通信分开，对外提供统一调用接口，减少业务 UI 与底层 <code>sip.js</code> 的直接耦合。</li><li><strong>跨页面状态共享：</strong> 在满足共享条件的页面间，通过隐藏 iframe、SharedWorker 和 MessagePort 传递呼叫状态；远端状态回放使用静默更新路径，避免再次被识别为本地修改并形成同步回环。</li><li><strong>多宿主兼容：</strong> 适配 iframe、钉钉等宿主环境；SharedWorker 不可用时复用核心业务处理逻辑，保留单页调用能力，并明确降级后的能力边界。</li><li><strong>通信链路排障：</strong> 结合请求限频、WebRTC 埋点和日志分析定位呼叫异常，参与单呼 / 群呼状态整合及复杂通信链路维护。</li></ul><h3 id="四、物联网能源管理平台-业务页面与数据可视化" tabindex="-1">四、物联网能源管理平台｜业务页面与数据可视化 <a class="header-anchor" href="#四、物联网能源管理平台-业务页面与数据可视化" aria-label="Permalink to &quot;四、物联网能源管理平台｜业务页面与数据可视化&quot;">​</a></h3><p><strong>Web 前端开发｜Vue 2、Vue 3、ECharts、Vite</strong></p><p><strong>项目背景：</strong> 参与物联网能源管理平台从 0 到 1 建设，负责业务页面、数据可视化和公共组件，服务能源数据查询与展示场景。</p><ul><li>负责业务页面和 ECharts 图表开发，将接口数据整理为页面和图表所需的展示结构，处理查询条件、空数据和异常状态。</li><li>主导 Vue 2 → Vue 3、Vuex → Pinia、vue-cli → Vite 迁移，处理依赖兼容、构建配置和模块拆分问题。</li><li>结合按需引入和构建配置优化，将构建耗时由约 60 秒降至 15 秒，缩短约 75%。</li></ul><h2 id="教育背景" tabindex="-1">教育背景 <a class="header-anchor" href="#教育背景" aria-label="Permalink to &quot;教育背景&quot;">​</a></h2><p><strong>湖南科技大学｜物联网工程｜全日制本科</strong><br> 2019.09—2023.06｜CET-6</p>',33)])])}const p=t(n,[["render",i]]);export{u as __pageData,p as default};
